FUNCTION_BLOCK FB_Contador
VAR_INPUT
    sensorPieza : BOOL; // Sensor fotoeléctrico que detecta la pieza
    btnReset : BOOL;    // Botón de reset para reiniciar el contador
END_VAR

VAR_OUTPUT
    loteListo : BOOL; // Salida que indica que se ha completado un lote
    cuenta : INT;      // Contador de piezas
END_VAR

VAR
    sensorAnterior : BOOL; // Variable para almacenar el estado anterior del sensor
END_VAR

// Inicialización del sensorAnterior con el valor actual del sensorPieza
IF sensorPieza THEN
    sensorAnterior := TRUE;
ELSE
    sensorAnterior := FALSE;
END_IF

// Lógica de conteo
IF sensorPieza AND NOT sensorAnterior THEN
    cuenta := cuenta + 1;
END_IF

// Actualización del sensorAnterior
sensorAnterior := sensorPieza;

// Lógica para detectar el lote completo
IF cuenta >= 12 THEN
    loteListo := TRUE;
ELSE
    loteListo := FALSE;
END_IF

// Lógica de reset
IF btnReset THEN
    cuenta := 0;
    loteListo := FALSE;
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Ventilador
VAR_INPUT
    quemadorOn : BOOL; // Indica si el quemador está encendido
END_VAR

VAR_OUTPUT
    ventilador : BOOL; // Controla el ventilador
END_VAR

VAR
    timer : TON; // Timer de retardo
    timerDone : BOOL; // Indica si el timer ha terminado
END_VAR

// Inicialización del timer
IF NOT timerDone THEN
    timer(IN := NOT quemadorOn, PT := T#30S);
    timerDone := timer.Q;
END_IF;

// Control del ventilador
IF quemadorOn OR NOT timerDone THEN
    ventilador := TRUE;
ELSE
    ventilador := FALSE;
END_IF;

FUNCTION_BLOCK FB_Ventilador
VAR_INPUT
    quemadorOn : BOOL; // Estado del quemador (TRUE si encendido, FALSE si apagado)
END_VAR

VAR_OUTPUT
    ventilador : BOOL; // Estado del ventilador (TRUE si encendido, FALSE si apagado)
END_VAR

VAR
    timer : TON; // Timer de retardo
    timerDone : BOOL; // Bandera para indicar si el timer ha terminado
END_VAR

// Inicialización del timer
IF NOT timerDone THEN
    timer(IN := NOT quemadorOn, PT := T#30S);
    timerDone := timer.Q;
END_IF;

// Control del ventilador
IF quemadorOn OR (NOT quemadorOn AND NOT timerDone) THEN
    ventilador := TRUE;
ELSE
    ventilador := FALSE;
END_IF;
